"""Create the illustrated, offline HTML manuals from verified release workflows.

Run from the workspace containing output/playwright/manuals screenshots, or use
the already bundled docs/manuals/assets/screenshots. PDF printing is separate.
"""
from pathlib import Path
import html
import re
import shutil

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / 'docs/manuals'
ASSETS = OUT / 'assets/screenshots'
OUT.mkdir(parents=True, exist_ok=True)
ASSETS.mkdir(parents=True, exist_ok=True)
for source in (ROOT / 'output/playwright/manuals').glob('*.png'):
    shutil.copyfile(source, ASSETS / source.name)


def p(text):
    return '<p>' + text + '</p>'


def steps(*items):
    return '<ol>' + ''.join('<li>' + item + '</li>' for item in items) + '</ol>'


def note(text):
    return '<aside>' + text + '</aside>'


def code(text, result, terminal='Ubuntu / Linux'):
    return '<div class="command"><b>พิมพ์ใน ' + terminal + '</b><pre><code>' + html.escape(text) + '</code></pre></div><p class="expected"><b>ผลที่ควรเห็น:</b> ' + result + '</p>'


def fig(name, caption):
    if not (ASSETS / (name + '.png')).is_file():
        raise RuntimeError('Missing verified screenshot: ' + name)
    return '<figure><a href="assets/screenshots/' + name + '.png" target="_blank"><img src="assets/screenshots/' + name + '.png" alt="' + html.escape(caption, quote=True) + '"></a><figcaption>' + caption + '</figcaption></figure>'


def flow(*items):
    return '<div class="flow">' + '<span class="arrow">→</span>'.join('<b>' + x + '</b>' for x in items) + '</div><p class="small">ภาพอธิบายขั้นตอน ไม่ใช่ภาพหน้าจอของระบบปฏิบัติการ</p>'


def table(headers, rows):
    return '<table><thead><tr>' + ''.join('<th>' + h + '</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<td>' + c + '</td>' for c in row) + '</tr>' for row in rows) + '</tbody></table>'


CSS = '''@font-face{font-family:Sarabun;src:url(assets/fonts/Sarabun-Regular.ttf)}
@font-face{font-family:Sarabun;src:url(assets/fonts/Sarabun-Bold.ttf);font-weight:700}
*{box-sizing:border-box}html{background:#e8edf6}body{font:14pt/1.28 Sarabun,sans-serif;color:#14213d;max-width:900px;margin:auto;background:white;padding:35px}
h1{font-size:26pt;line-height:1.2;color:#174ce6}h2{font-size:18pt;line-height:1.25;color:#174ce6;border-bottom:3px solid #fa745f;padding-bottom:8px;margin:0 0 15px}h3{font-size:16pt;margin:16px 0 8px}p{margin:9px 0}li{margin:8px 0}ol,ul{padding-left:26px}a{color:#174ce6;text-decoration:underline}
.cover{min-height:760px;display:flex;flex-direction:column;justify-content:center}.kicker{background:#174ce6;color:white;padding:9px 15px;width:fit-content;font-weight:700}.subtitle{font-size:19pt}.version{color:#536078;margin-top:28px}.chapter{padding-top:22px;margin-top:35px}.chapter-number{font-size:12pt;color:#536078}aside{background:#fff0eb;border-left:5px solid #fa745f;padding:12px;margin:15px 0}pre{font:10.5pt/1.35 Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#edf2ff;padding:12px;border:1px solid #c0cdea;color:#172a51;margin:7px 0}code{font:inherit}.command{break-inside:avoid}.expected{background:#e8f5ec;padding:9px;border-left:4px solid #27935a}.small,figcaption{font-size:11pt;line-height:1.3;color:#495770}figure{margin:16px 0;break-inside:avoid}img{width:100%;height:auto;border:1px solid #000;display:block}figcaption{margin-top:6px}table{width:100%;border-collapse:collapse;font-size:12.5pt;margin:14px 0}th{background:#e8edff}td,th{border:1px solid #bdc8da;padding:8px;text-align:left;vertical-align:top}tr{break-inside:avoid}.flow{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:18px 0}.flow b{background:#174ce6;color:white;padding:10px}.arrow{color:#fa745f;font-weight:700}.nav{background:#edf2ff;padding:18px}button{background:#fa745f;border:0;color:#14213d;padding:10px 18px;font:700 13pt Sarabun;cursor:pointer}.printbar{position:sticky;top:0;background:#14213d;color:white;padding:10px;z-index:2;display:flex;gap:15px;align-items:center}.printbar a{color:white}
@page{size:A4;margin:20mm 20mm 20mm 25mm}@media print{html,body{background:white;width:auto;max-width:none;margin:0;padding:0;font-size:14pt}.printbar{display:none}.cover{min-height:230mm;break-after:page}.chapter{break-before:page;padding:0;margin:0}.nav{background:#edf2ff}a{text-decoration:none;color:#14213d}h1{font-size:26pt}h2{font-size:18pt}p,li{orphans:3;widows:3}figure{max-width:100%}pre{font-size:10pt}img{max-height:115mm;object-fit:contain}h2,h3{break-after:avoid}table{font-size:12pt}}
'''


def manual(slug, title, subtitle, chapters, scope):
    toc = '<div class="nav"><h2>เปิดอ่านตามหัวข้อ</h2><ol>' + ''.join('<li><a href="#chapter-' + str(i) + '">' + name + '</a></li>' for i, (name, _) in enumerate(chapters, 1)) + '</ol></div>'
    cover = '<section class="cover"><div class="kicker">SMH LEARNING · PRODUCTION 1.0</div><h1>' + title + '</h1><p class="subtitle">' + subtitle + '</p>' + flow('เตรียม', 'ทำทีละขั้น', 'ตรวจผล', 'ใช้งาน') + p(scope) + '<p class="version">รุ่น 1.0.0 · ปรับปรุง 10 ตุลาคม 2569<br>สำหรับผู้เริ่มต้น · ภาพประกอบและข้อมูลสมมติจากชุดทดสอบ</p></section>'
    body = cover + '<section class="chapter">' + toc + note('อ่านจาก HTML: คลิกภาพเพื่อเปิดภาพเต็มและขยายดูข้อความได้ คัดลอกคำสั่งจาก HTML เพื่อคงบรรทัดเดิม อ่านจาก PDF: ใช้ปุ่มขยาย 150–200% และค้นหาคำด้วย Ctrl+F ไฟล์ HTML อยู่ใน source ZIP ที่ docs/manuals/index.html ภาพที่แสดงชื่อบุคคลใช้ข้อมูลสมมติทั้งหมด') + '</section>'
    for i, (name, content) in enumerate(chapters, 1):
        # Keep one readable screenshot with its steps on each printed chapter.
        # Additional screenshots remain available at full resolution in HTML.
        figures = list(re.finditer(r'<figure>.*?</figure>', content, flags=re.S))
        for match in reversed(figures[1:]):
            content = content[:match.start()] + '<details class="extra-image"><summary>เปิดภาพเพิ่มเติมของหัวข้อนี้</summary>' + match.group() + '</details>' + content[match.end():]
        body += '<section class="chapter" id="chapter-' + str(i) + '"><p class="chapter-number">ขั้นตอน / หัวข้อ ' + str(i) + '</p><h2>' + name + '</h2>' + content + '</section>'
    body += '<section class="chapter"><h2>ข้อมูลเอกสารและแหล่งอ้างอิง</h2>' + p('จัดทำจากซอร์สรุ่น 1.0.0 และการติดตั้งจริงใน Ubuntu 24.04.5 บน WSL2 วันที่ 10 ตุลาคม 2569 ไม่ใช้ภาพหน้าจอ AlmaLinux หรือ Windows ที่ไม่ได้ถ่ายจริง รูปแบบแผนภาพมีคำกำกับแยกจากภาพหน้าจอ') + p('ใช้ฟอนต์ Sarabun ของ Google Fonts ภายใต้ SIL Open Font License เพราะเครื่องจัดทำไม่มี TH SarabunPSK ไฟล์ใบอนุญาตอยู่ใน assets/fonts/OFL.txt') + p('ดู <a href="../PRODUCTION_1_0_VERIFICATION.md">ผลการทดสอบ</a> และ <a href="https://github.com/golderboy/smh-learn">ซอร์ส GitHub</a> ก่อนติดตั้งจริง') + '<ul><li><a href="https://docs.docker.com/engine/install/ubuntu/">Docker บน Ubuntu</a></li><li><a href="https://docs.docker.com/engine/install/rhel/">Docker บน RHEL</a> และ <a href="https://wiki.almalinux.org/repos/Extras.html">AlmaLinux CRB/EPEL</a></li><li><a href="https://learn.microsoft.com/en-us/windows/wsl/install">Microsoft WSL</a> / <a href="https://learn.microsoft.com/en-us/windows/wsl/systemd">systemd</a> / <a href="https://learn.microsoft.com/en-us/windows/wsl/networking">เครือข่าย</a></li><li><a href="https://eff-certbot.readthedocs.io/en/stable/using.html#webroot">Certbot webroot</a></li></ul></section>'
    (OUT / (slug + '.html')).write_text('<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + title + '</title><style>' + CSS + '\nsummary{color:#174ce6;cursor:pointer;margin:10px 0}@media print{.extra-image{display:none}}</style></head><body><div class="printbar"><a href="index.html">คู่มือทั้งหมด</a><button onclick="print()">พิมพ์ / บันทึก PDF</button></div>' + body + '</body></html>', encoding='utf-8')


PREP = ('เริ่มจากสิ่งที่ต้องเตรียม', p('คู่มือนี้เริ่มหลังติดตั้งระบบปฏิบัติการแล้ว เตรียมเครื่องเฉพาะสำหรับระบบ ไม่ใช้เครื่องที่มีฐานข้อมูลหน่วยงานอยู่แล้ว ผู้ติดตั้งต้องมีสิทธิ์ผู้ดูแลเครื่องและเชื่อมต่ออินเทอร์เน็ต หากยังไม่มีเครื่องหรือโดเมน ให้นำรายการนี้ให้เจ้าหน้าที่ IT เตรียมก่อน') + table(['สิ่งที่เตรียม', 'ทำอย่างไร'], [['เครื่อง', 'เริ่มที่ CPU 4 แกน / RAM 8 GB / SSD 100 GB เป็นค่าจัดสรรเริ่มต้น ไม่ใช่ผลทดสอบผู้ใช้พร้อมกัน 1,000 คน'], ['ชื่อเว็บไซต์', 'เช่น learning.หน่วยงาน.org ให้ IT ตั้ง DNS ชี้มาที่เครื่อง ใช้ชื่อจริงแทน learning.example.org ในคำสั่ง'], ['อีเมลผู้ดูแล', 'ใช้รับการแจ้งเตือนใบรับรอง เช่น admin@หน่วยงาน.org'], ['IP ผู้ติดตั้ง', 'ให้ IT ระบุ IP ที่เข้าถึงเครื่อง เพื่อเปิด HTTPS เฉพาะผู้ดูแลระหว่างเปลี่ยนรหัสแรก'], ['สำรองข้อมูล', 'มีที่เก็บนอกเครื่อง และผู้ถือกุญแจถอดรหัสสำรอง'], ['สิทธิ์', 'บัญชี Linux ที่ใช้ sudo ได้ หรือ Windows ที่เป็น Administrator']]) + note('คำสั่งที่มี example.org และ 203.0.113.10 เป็นตัวอย่าง ต้องแทนค่าจริงก่อนกด Enter หากไม่มีโดเมนสาธารณะ ต้องใช้ใบรับรองขององค์กรโดยให้ IT ช่วยติดตั้ง ไม่เปิดใช้ Production ผ่าน HTTP'))

TERMINAL = ('รู้จักหน้าต่างพิมพ์คำสั่ง', steps('Linux ที่มีหน้าจอ: เปิดโปรแกรม Terminal หากเป็นเซิร์ฟเวอร์ให้ IT แจ้ง IP และชื่อบัญชี แล้วเปิด PowerShell บน Windows และพิมพ์ ssh ชื่อบัญชี@IPเครื่อง', 'พิมพ์รหัส Linux แล้วกด Enter ระหว่างพิมพ์อาจไม่เห็นตัวอักษร นี่เป็นพฤติกรรมปกติ รหัส Linux คนละรหัสกับบัญชี admins ของเว็บไซต์', 'คัดลอกคำสั่งหนึ่งกรอบ วางใน Terminal แล้วกด Enter รอจนมีบรรทัดให้พิมพ์คำสั่งใหม่ อย่าปิดหน้าต่างระหว่างติดตั้ง', 'หากมี Error หรือสีแดง ให้หยุดขั้นนั้น เก็บข้อความเพื่อให้ IT ตรวจ ไม่ข้ามไปขั้นถัดไป') + code('whoami\npwd\ndate', 'เห็นชื่อบัญชี ตำแหน่งโฟลเดอร์ และวันเวลาที่ถูกต้อง') + flow('คัดลอก', 'วางใน Terminal', 'กด Enter', 'รอผล') + p('คำว่า sudo หมายถึงทำงานด้วยสิทธิ์ผู้ดูแล คำว่า cd หมายถึงเข้าโฟลเดอร์ Docker คือโปรแกรมที่แยกเว็บ ฐานข้อมูล และบริการออกเป็นกล่องทำงาน คำว่า volume คือพื้นที่เก็บข้อมูลที่ยังอยู่เมื่ออัปเดตกล่อง'))

UBUNTU_TOOLS = ('ติดตั้งเครื่องมือใน Ubuntu 24.04', p('คำสั่งชุดนี้ทดสอบจริงใน Ubuntu 24.04.5 บน WSL2 ใช้ Docker Engine ภายใน Linux ไม่ต้องลง PHP, Node หรือ MariaDB บนเครื่อง host หากเครื่องมี Docker/Podman หรือบริการอื่นอยู่แล้ว ให้ IT ตรวจความเข้ากันได้ก่อน') + code('sudo apt-get update\nsudo apt-get install -y ca-certificates curl git python3 nginx openssl gnupg certbot\nsudo install -m 0755 -d /etc/apt/keyrings\nsudo curl -fsSL https://download.docker.com/linux/ubuntu/gpg -o /etc/apt/keyrings/docker.asc\nsudo chmod a+r /etc/apt/keyrings/docker.asc', 'ดาวน์โหลดเสร็จ ไม่มีข้อความติดตั้งล้มเหลว') + code('sudo tee /etc/apt/sources.list.d/docker.sources >/dev/null <<\'EOF\'\nTypes: deb\nURIs: https://download.docker.com/linux/ubuntu\nSuites: noble\nComponents: stable\nArchitectures: amd64\nSigned-By: /etc/apt/keyrings/docker.asc\nEOF\nsudo apt-get update\nsudo apt-get install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin\nsudo systemctl enable --now docker\nsudo /usr/bin/docker run --rm hello-world\nsudo /usr/bin/docker compose version', 'เห็น Hello from Docker! และหมายเลข Docker Compose ใช้ชุดนี้กับ x86_64 / amd64 เท่านั้น'))

ALMA_TOOLS = ('ติดตั้งเครื่องมือใน AlmaLinux 9', p('ตรวจว่าเป็น AlmaLinux 9 ก่อน คำสั่งอ้างอิง Docker repository สำหรับ RHEL 9 และ AlmaLinux CRB/EPEL ยังไม่ได้ยืนยันจากการรันจริงบนเครื่อง AlmaLinux 9 การใช้ repository นี้อาศัยความเข้ากันได้กับ RHEL ให้ IT ตรวจแพ็กเกจเดิมก่อน ไม่ปิด SELinux') + code('cat /etc/almalinux-release\ngetenforce\nsudo dnf install -y git python3 nginx firewalld openssl gnupg2 dnf-plugins-core policycoreutils-python-utils\nsudo dnf config-manager --set-enabled crb\nsudo dnf install -y epel-release certbot\nsudo dnf config-manager --add-repo https://download.docker.com/linux/rhel/docker-ce.repo\nsudo dnf install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin\nsudo systemctl enable --now docker\nsudo docker run --rm hello-world\nsudo docker compose version\nsudo setsebool -P httpd_can_network_connect 1', 'ระบบเป็นรุ่น 9, SELinux Enforcing, เห็น Hello from Docker! และ Docker Compose version', 'AlmaLinux Terminal') + note('หากโปรแกรมติดตั้งแจ้งชนกับ Podman/Docker เดิม อย่าลบแพ็กเกจหรือข้อมูลเดิมเอง ให้ IT ตรวจบริการอื่นก่อน การเปิด httpd_can_network_connect ใช้ให้ Nginx ติดต่อ backend ไม่ใช่การปิด SELinux'))

SOURCE = ('ดาวน์โหลดรุ่น 1.0.0 และติดตั้งเว็บ', steps('แทน learning.example.org ด้วยชื่อเว็บไซต์จริงของหน่วยงาน ห้ามใส่ https:// หรือ / ต่อท้ายใน --domain', 'คัดลอกคำสั่งแล้วรอ build อาจใช้เวลาหลายนาทีตามอินเทอร์เน็ต เมื่อจบต้องไม่มี Error', 'เก็บ .env.production เป็นความลับ ไฟล์นี้มีรหัสฐานข้อมูลและกุญแจเข้ารหัส อย่าส่งลงแชตหรือ GitHub') + code('sudo install -d -m 0750 -o "$USER" -g "$(id -gn)" /opt/smh-learn\ngit clone --branch v1.0.0 https://github.com/golderboy/smh-learn.git /opt/smh-learn\ncd /opt/smh-learn\npython3 scripts/setup-production.py --domain learning.example.org\nchmod 600 .env.production\nsudo sh scripts/install-production.sh', 'เห็น production_http_verified: true และ Services started. มีฐานข้อมูลใหม่และบัญชี admins ไม่มีผู้ใช้/บทเรียนทดสอบ') + code('dc() { sudo /usr/bin/docker compose --env-file .env.production -f compose.production.yaml "$@"; }\ndc ps\ndc exec -T nginx nginx -t', 'บริการ app, nginx, mariadb, redis, queue-worker, scheduler ทำงาน และ nginx configuration test is successful') + note('หากกลับมาทำต่อวันอื่นให้ cd /opt/smh-learn แล้วสร้าง dc() ใหม่ก่อนใช้คำสั่ง dc การติดตั้งซ้ำด้วย install-production.sh ใช้ข้อมูลเดิมและไม่รีเซ็ตรหัส ห้ามลบ .env.production หรือใช้ migrate:fresh / down -v'))

TLS = ('ติดตั้งกุญแจ HTTPS ก่อนเข้าสู่ระบบ', p('HTTPS ทำให้เบราว์เซอร์แสดงการเชื่อมต่อปลอดภัย โดเมนต้องชี้เครื่องและพอร์ต 80 เข้าได้จากอินเทอร์เน็ตก่อนใช้ Let’s Encrypt ให้แทนค่าโดเมนและอีเมลในสองบรรทัดแรก หากเป็นระบบภายใน ให้ IT ใช้ใบรับรององค์กรแทนขั้นขอ Certbot') + code('cd /opt/smh-learn\nSMH_DOMAIN=learning.example.org\nSMH_EMAIL=admin@example.org\nsudo install -d -m 0755 /var/www/letsencrypt\nsed "s/learning.example.org/$SMH_DOMAIN/g" docker/production/host-nginx.conf.example | sudo tee /etc/nginx/conf.d/smh-learning.conf >/dev/null\nsudo nginx -t\nsudo systemctl enable --now nginx\nsudo certbot certonly --webroot -w /var/www/letsencrypt -d "$SMH_DOMAIN" --email "$SMH_EMAIL" --agree-tos --no-eff-email', 'nginx -t ผ่าน และ Certbot แจ้งรับ certificate สำเร็จ ถ้าขอไม่ได้ให้หยุดและแก้ DNS/พอร์ต/อีเมลก่อน') + code('sed "s/learning.example.org/$SMH_DOMAIN/g" docker/production/host-nginx-tls.conf.example | sudo tee /etc/nginx/conf.d/smh-learning.conf >/dev/null\nsudo nginx -t\nsudo systemctl reload nginx\ncurl -I "https://$SMH_DOMAIN/up"\nsudo certbot renew --dry-run', 'เว็บ /up ตอบ HTTP 200 และการจำลองต่ออายุผ่าน ห้ามกดข้ามคำเตือนใบรับรองบนเว็บ Production') + p('ชุดทดสอบใช้ใบรับรองชั่วคราวกับ loopback เพื่อทดสอบ secure cookie เท่านั้น การออกและต่ออายุใบรับรองสาธารณะ ยังไม่ได้ยืนยันจากการรันจริง ต้องตรวจบนเครื่องขององค์กร'))

ALMA_FW = ('เปิด Firewall เฉพาะผู้ดูแลระหว่างตั้งต้น', p('ให้ IT ตรวจ SSH และ zone ก่อนเปิด Firewall เพื่อไม่ตัดการเชื่อมต่อ ใส่ IP จริงของผู้ดูแลแทน 203.0.113.10 ในบรรทัด rich-rule เปิด HTTP เฉพาะเพื่อขอใบรับรอง ยังไม่เปิดหน้า login ผ่าน HTTP') + code('sudo systemctl enable --now firewalld\nsudo firewall-cmd --get-active-zones\nsudo firewall-cmd --permanent --add-service=ssh\nsudo firewall-cmd --permanent --add-service=http\nsudo firewall-cmd --permanent --add-rich-rule=\'rule family="ipv4" source address="203.0.113.10/32" port port="443" protocol="tcp" accept\'\nsudo firewall-cmd --reload\nsudo firewall-cmd --list-all', 'SSH ยังเข้าได้ เปิด 80 และเปิด 443 เฉพาะ IP ผู้ดูแล ต้องใช้ zone ที่ผูกกับ interface จริง หากมี IPv6 ให้ IT กำหนดนโยบายแยก', 'AlmaLinux Terminal') + p('หลังเปลี่ยนรหัส admins ตรวจรับระบบ และ backup ผ่านแล้ว จึงเปิด HTTPS ตามนโยบายหน่วยงาน เครื่องที่ใช้ภายในอาจอนุญาตเฉพาะ subnet') + code('sudo firewall-cmd --permanent --add-service=https\nsudo firewall-cmd --reload', 'ผู้ใช้ที่องค์กรอนุญาตเข้าถึง HTTPS ได้ ทำขั้นนี้หลังตรวจรับและเปลี่ยนรหัสแรกเท่านั้น', 'AlmaLinux Terminal'))

UBUNTU_FW = ('ตั้ง Firewall ก่อนเปิดให้ทุกคน', p('คำสั่งนี้สำหรับ Ubuntu Server ใหม่ที่ไม่มีนโยบาย Firewall เดิม ใช้ IP ผู้ดูแลจริงแทน 203.0.113.10 หากเป็น WSL ให้ใช้หัวข้อเครือข่าย Windows แทน ไม่เปิด UFW ใน WSL ตามตัวอย่างนี้') + code('sudo apt-get install -y ufw\nsudo ufw allow OpenSSH\nsudo ufw allow 80/tcp\nsudo ufw allow from 203.0.113.10 to any port 443 proto tcp\nsudo ufw enable\nsudo ufw status', 'SSH ยังใช้ได้ พอร์ต 443 อนุญาตเฉพาะ IP ผู้ดูแล ตรวจ firewall ภายนอกและ IPv6 กับ IT ด้วย') + p('หลังเปลี่ยนรหัส admins และตรวจรับครบแล้วจึงให้ IT เปิด HTTPS สำหรับกลุ่มที่ต้องใช้งาน') + code('sudo ufw allow 443/tcp\nsudo ufw status', 'เปิด HTTPS หลังตรวจรับแล้ว โดยไม่เปิด backend 8080 หรือฐานข้อมูลสู่ LAN/Internet') + note('การตั้ง UFW บน Ubuntu Server จริง ยังไม่ได้ยืนยันจากการรันจริงในการทดสอบ WSL รอบนี้'))

ONBOARD = ('เข้าสู่ระบบครั้งแรกและนำเข้าข้อมูล', steps('เปิด Chrome หรือ Edge พิมพ์ https://ชื่อเว็บไซต์จริง/login ในช่องที่อยู่ด้านบน ไม่ใช่ช่องค้นหา', 'บัญชีตั้งต้น username: admins รหัสแรก: P@ssw0rd112233 กดเข้าสู่ระบบ แล้วเปลี่ยนรหัสทันทีอย่างน้อย 10 ตัวอักษร หากเป็นการติดตั้งซ้ำให้ใช้รหัสล่าสุดของเจ้าของ', 'เลือก ตั้งค่าเว็บไซต์ ปรับชื่อหน่วยงาน ภาพ และข้อความ จากนั้นเลือก นำเข้าข้อมูลพื้นฐาน', 'ดาวน์โหลดเทมเพลตและนำเข้า แผนก → ตำแหน่ง → หมวด → ผู้ใช้ → ร้าน ตรวจตัวอย่างก่อนยืนยันทุกครั้ง', 'ทำหลักสูตรทดสอบด้วยข้อมูลสมมติในฐานข้อมูลใหม่ เรียนจริงจนจบ และตรวจรายงานก่อนเปิดใช้จริง') + fig('login', '1 ช่องเลขประจำตัว/บัญชี admins · 2 ช่องรหัสผ่าน · 3 ปุ่มเข้าสู่ระบบ ภาพนี้เป็นชุดทดสอบแยก') + fig('change-password', 'ตั้งรหัสใหม่และพิมพ์ซ้ำให้ตรงกัน ระบบบังคับเปลี่ยนก่อนเปิด Dashboard') + p('ผู้ใช้นำเข้าใหม่ username คือเลขประจำตัว รหัสแรก learn123456 บทบาทผู้เรียน บังคับเปลี่ยนก่อนใช้ เลขซ้ำถูกข้าม ไม่แทนข้อมูลเดิม ร้านที่นำเข้ายังรอ Admin อนุมัติ ดูคู่มือ Admin สำหรับขั้นตอนละเอียด'))

VERIFY = ('ตรวจผลก่อนเปิดใช้งานจริง', code('cd /opt/smh-learn\ndc() { sudo /usr/bin/docker compose --env-file .env.production -f compose.production.yaml "$@"; }\ndc exec -T app composer check-platform-reqs --no-dev\ndc exec -T app php artisan ops:release-check --json\ndc exec -T app php artisan ops:check --queue --tls --json', 'platform ผ่าน, release-check ทุกข้อพร้อม และ ops:check ผ่าน รอ scheduler อย่างน้อยหนึ่งนาทีก่อนตรวจ TLS ต้องเป็น certificate เชื่อถือได้และเหลืออย่างน้อย 14 วัน') + table(['ทดลอง', 'ต้องได้ผล'], [['Pretest', 'ยังไม่สอบต้องเปิดบทเรียนไม่ได้ สอบได้ 0% ก็เรียนได้'], ['บทเรียน', 'วิดีโอเล่นได้ PDF แสดงใต้คลิป เลื่อนข้ามคลิปไม่ได้ บทถัดไปปิดก่อนครบเกณฑ์'], ['Posttest', 'เรียนครบก่อนสอบ ทำอย่างน้อยหนึ่งครั้งจึงจบ ใช้จำนวนครั้งที่ตั้งในระบบ'], ['รายงาน / แต้ม', 'เห็นเฉพาะข้อมูลตามสิทธิ์ โบนัสจบ20 / ผ่าน30 / สูง90%เพิ่ม10'], ['ร้าน / คูปอง', 'ร้านต้องได้รับอนุมัติ คูปองใช้ได้ครั้งเดียว ใบเบิกไม่จ่ายเงินจริง'], ['ThaiD', 'ปิดอยู่จนเชื่อมกับองค์กรและทดสอบบนเซิร์ฟเวอร์จริง']]) + p('เก็บผลตรวจให้ผู้รับผิดชอบยอมรับก่อนเปิด Firewall ทั่วไป หากมี false หรือ Error ให้ตรวจหัวข้อแก้ปัญหา ไม่ข้ามโดยแก้ APP_DEBUG เป็น true'))

BACKUP = ('สำรองข้อมูลและกู้คืนอย่างปลอดภัย', p('สำรองก่อนเปิดบริการ และทุกวันหลังเปิดใช้งาน คำสั่งนี้สร้างกุญแจครั้งแรกเพียงครั้งเดียว ห้ามสร้างทับกุญแจที่ใช้กับ backup เดิม ให้เจ้าหน้าที่ผู้รับผิดชอบเก็บสำเนากุญแจคนละที่กับไฟล์สำรอง') + code('cd /opt/smh-learn\nsudo install -d -m 0700 /etc/smh-learning\nsudo test ! -e /etc/smh-learning/backup.pass && sudo sh -c \'umask 077; openssl rand -base64 48 > /etc/smh-learning/backup.pass\'\nsudo python3 scripts/backup-production.py --passphrase-file /etc/smh-learning/backup.pass\ndc exec -T app php artisan ops:check --queue --backup --json', 'เห็น verified: true และไฟล์เข้ารหัส .tar.gz.gpg กับ .json ใน .backups ขณะสำรองเว็บพักชั่วคราวแล้วเปิดกลับพร้อม worker') + code('sudo install -m 0644 docker/production/smh-backup.service docker/production/smh-backup.timer /etc/systemd/system/\nsudo systemctl daemon-reload\nsudo systemctl enable --now smh-backup.timer\nsudo systemctl list-timers smh-backup.timer', 'เห็นเวลาสำรองรายวัน ตรวจ timedatectl ให้ตรงเวลา Asia/Bangkok') + p('ส่งสำเนา .tar.gz.gpg และ .json ออกนอกเครื่องตามนโยบาย IT กำหนดการเก็บย้อนหลังเอง โปรแกรมไม่ลบไฟล์เก่าให้ การมี verified หมายถึงเข้ารหัสและตรวจไฟล์แล้ว ต้องทดสอบกู้คืนด้วย') + note('กู้คืนในระบบแยกเท่านั้น เปิดเอกสาร PRODUCTION_OPERATIONS.md และทำตาม restore-production.py โปรแกรมปฏิเสธฐานข้อมูลที่ไม่ว่าง การกู้คืนจริงที่ใช้ข้อมูลใหม่แล้วต้องให้เจ้าของข้อมูลตัดสินใจ ห้ามผู้เริ่มต้นใช้ down -v / migrate:fresh เพื่อแก้ปัญหา'))

RENEW = ('ต่ออายุ HTTPS และเปิดเครื่องวันถัดไป', code('cd /opt/smh-learn\nsudo install -m 0644 docker/production/smh-certbot-renew.service docker/production/smh-certbot-renew.timer /etc/systemd/system/\nsudo systemctl daemon-reload\nsudo systemctl enable --now smh-certbot-renew.timer\nsudo systemctl list-timers smh-certbot-renew.timer\nsudo systemctl is-enabled docker nginx', 'มี timer ต่ออายุและ docker/nginx เปิดอัตโนมัติบน Linux host ที่เปิดตลอดเวลา') + p('หลังรีบูตเครื่องเซิร์ฟเวอร์จริงให้ทดสอบเข้าเว็บ dc ps และ ops:check อีกครั้ง การรีบูตเครื่องจริงและไฟดับยังไม่ได้ยืนยันจากการรันจริงรอบนี้ WSL ต้องเปิด Linux session ค้างไว้ตามคู่มือ Windows') + p('การอัปเดตให้สำรองและทดสอบรุ่นใหม่แยกก่อน ใช้ขั้นตอนใน PRODUCTION_OPERATIONS.md ห้ามเปลี่ยน APP_KEY หรือชื่อ project เมื่อมีข้อมูลแล้ว'))

TROUBLE = ('เมื่อทำแล้วไม่ตรงกับคู่มือ', table(['อาการ', 'ทำทีละข้อ'], [['permission denied เมื่อใช้ Docker', 'ใช้ sudo docker และตรวจ systemctl status docker อย่า chmod 777'], ['Clone บอกโฟลเดอร์ไม่ว่าง', 'อย่าลบโฟลเดอร์ ให้ IT ตรวจว่าเป็นการติดตั้งเดิมหรือไม่'], ['502 Bad Gateway', 'รอ build/start จบ ตรวจ dc ps และ dc logs --tail 50 app nginx บน Alma ตรวจ SELinux/AVC เพิ่ม'], ['419 / เข้าระบบแล้วหลุด', 'ใช้ HTTPS ชื่อโดเมนตรง APP_URL ตรวจใบรับรอง/เวลา/Redis อย่าปิด secure cookie'], ['PDF / วิดีโอเปิดไม่ได้', 'ตรวจ Pretest สิทธิ์ผู้เรียน dc exec -T nginx nginx -t และ UID PHP/Nginx ต้อง33 อย่าเปิด media เป็นไฟล์สาธารณะ'], ['ไฟล์ Excel ไม่ผ่าน', 'ใช้เทมเพลตตรงหัวข้อ เก็บชื่อคอลัมน์/ชีต ไม่มีสูตร เก็บเลขเป็น Text แก้ทุกแถวตามข้อความก่อนส่งใหม่'], ['WSL เว็บเข้าไม่ได้', 'เปิด WSL session ค้างไว้ ตรวจ systemd/Docker/Nginx อย่าใช้ wsl --shutdown กระทบระบบอื่น'], ['พื้นที่เต็ม / Backup ไม่ผ่าน', 'ให้ IT ตรวจ df -h และพื้นที่ offsite ห้ามลบ volume เพื่อคืนพื้นที่']]) + p('ส่ง IT: ชื่อระบบปฏิบัติการ ขั้นที่ทำ วันเวลา ภาพข้อความผิดพลาดและ dc ps ปิดบังเลขบัตรประชาชน รหัสผ่าน APP_KEY และรหัสคูปอง ห้ามส่งไฟล์ .env.production หรือ backup.pass'))

manual('install-almalinux', 'คู่มือติดตั้งบน AlmaLinux 9', 'ตั้งแต่เตรียมเครื่องจนเปิดบริการอย่างมีขั้นตอน', [PREP, TERMINAL, ALMA_TOOLS, ALMA_FW, SOURCE, TLS, ONBOARD, VERIFY, BACKUP, RENEW, TROUBLE], 'ส่วนแอปทดสอบจริงบน Ubuntu WSL2 ส่วน AlmaLinux, SELinux, firewalld และใบรับรองของหน่วยงาน ยังไม่ได้ยืนยันจากการรันจริงบน AlmaLinux 9')
manual('install-ubuntu', 'คู่มือติดตั้งบน Ubuntu 24.04 LTS', 'ติดตั้ง Linux host ด้วย Docker Engine และ HTTPS', [PREP, TERMINAL, UBUNTU_TOOLS, UBUNTU_FW, SOURCE, TLS, ONBOARD, VERIFY, BACKUP, RENEW, TROUBLE], 'ทดสอบติดตั้งและนำเข้าจริงใน Ubuntu 24.04.5 บน WSL2 การเปิดพอร์ตภายนอก UFW และ Let’s Encrypt บนเซิร์ฟเวอร์จริง ยังไม่ได้ยืนยันจากการรันจริง')

WINDOWS = ('เปิด WSL2 บน Windows 11', steps('บันทึกงานและเตรียมรีสตาร์ตเครื่อง คลิก Start พิมพ์ PowerShell คลิกขวา Run as administrator แล้วกด Yes', 'รันคำสั่งกรอบแรก รอจบ หากแจ้งให้ restart ให้รีสตาร์ต Windows แล้วเปิด PowerShell ตามปกติ', 'ตรวจรายชื่อ Linux หากมี Ubuntu-24.04 ที่ใช้ระบบอื่นอยู่แล้ว อย่าติดตั้งทับ ให้ IT เตรียม Linux แยก คู่มือนี้ใช้ Ubuntu-24.04 สำหรับ SMH โดยเฉพาะ', 'หลังติดตั้ง Ubuntu ครั้งแรก ตั้งชื่อ Linux เช่น smhoperator และรหัส Linux ของตัวเอง รหัสไม่แสดงขณะพิมพ์ เก็บไว้เพราะต้องใช้กับ sudo') + code('wsl --install --no-distribution\nwsl --update', 'WSL ติดตั้ง/อัปเดตแล้ว หากแจ้ง reboot ให้รีสตาร์ต', 'PowerShell (Run as administrator)') + code('wsl --set-default-version 2\nwsl --list --verbose\nwsl --install -d Ubuntu-24.04\nwsl -d Ubuntu-24.04', 'เปิด Terminal Ubuntu ได้ และ wsl --list --verbose แสดง VERSION 2', 'PowerShell') + flow('Windows', 'WSL2 Ubuntu', 'Docker Engine', 'SMH Learning') + note('เส้นทาง Windows นี้ใช้ Linux ผ่าน WSL2 ไม่ใช่ XAMPP และไม่ต้องเปิด Docker Desktop integration ให้ distro เดียวกัน การเปิด WSL จาก Windows ที่ยังไม่เคยติดตั้งเลย ยังไม่ได้ยืนยันจากการรันจริงบนเครื่องใหม่'))
WSL_SERVICE = ('ตรวจ systemd และเปิด Linux ค้างไว้', code('ps -p 1 -o comm=\ncat /etc/os-release', 'เห็น systemd และ Ubuntu 24.04 ถ้าเป็น systemd อยู่แล้วข้ามกรอบถัดไป') + p('ถ้าไม่ใช่ systemd ให้ใช้ sudo nano /etc/wsl.conf อ่านไฟล์เดิมก่อน เพิ่มเฉพาะส่วน [boot] systemd=true ไม่ลบการตั้งค่าอื่น กด Ctrl+O → Enter → Ctrl+X แล้วกลับ PowerShell') + code('wsl --terminate Ubuntu-24.04\nwsl -d Ubuntu-24.04', 'เปิด Ubuntu ใหม่แล้ว ps -p 1 -o comm= เป็น systemd', 'PowerShell') + note('ใช้ terminate เฉพาะ distro นี้ ห้าม wsl --shutdown เพราะหยุด Linux ทุกชุดรวมระบบเดิม จากการทดสอบ WSL อาจหยุดเมื่อไม่มี session เปิด แม้เปิด systemd แล้ว') + code('sleep infinity', 'คำสั่งไม่มีข้อความและรอค้าง ให้เปิดหน้าต่างนี้ไว้ เปิด PowerShell อีกหน้าต่างแล้ว wsl -d Ubuntu-24.04 เพื่อทำขั้นถัดไป') + p('หากกด Ctrl+C หรือปิดทุกหน้าต่าง Ubuntu ระบบอาจหยุดและเว็บเข้าไม่ได้ สำหรับเปิดให้หน่วยงานใช้ตลอดเวลาให้ IT จัดการเริ่มงานตามบัญชี Windows และทดสอบหลังรีบูต/ออกจากระบบจริง การเริ่มอัตโนมัติและบริการ 24 ชั่วโมงบนเครื่องนี้ยังไม่ได้ยืนยันจากการรันจริง'))
WSL_NETWORK = ('เปิดเว็บบน Windows และเตรียมเครือข่าย', p('หลังติดตั้งเว็บและ HTTPS แล้ว เปิด Edge/Chrome บน Windows ด้วยชื่อโดเมนจริงที่ IT เตรียม WSL รองรับการเข้าถึง localhost จาก Windows แต่ยังต้องใช้ใบรับรองที่เชื่อถือได้สำหรับชื่อเว็บ อย่าเปิด Production ด้วย http://127.0.0.1:8080 เพราะ secure cookie ต้อง HTTPS') + table(['รูปแบบใช้งาน', 'สิ่งที่ต้องทำ'], [['เครื่องเดียว', 'ให้ IT ตั้งชื่อเว็บใน DNS/hosts และใบรับรององค์กร แล้วใช้ HTTPS ตามชื่อจริง backendเปิด loopback8080'], ['เครื่องอื่นใน LAN', 'ให้ IT ตั้ง WSL networking/port forwarding และ Windows Firewall สำหรับ443 กับ IP/subnetที่อนุญาต WSL IPอาจเปลี่ยนหลัง restart'], ['อินเทอร์เน็ต', 'ต้องมี DNS/router/firewall/certificateจริง ให้ IT รับผิดชอบก่อนเปิดผู้ใช้'], ['เก็บไฟล์', 'เก็บซอร์สใน /opt/smh-learn ของ Linux ไม่ใช้ /mnt/c สำหรับฐานข้อมูลหรือ Docker data']]) + p('การทดสอบรอบนี้เข้าผ่าน https://127.0.0.1:18443 ด้วยใบรับรองชั่วคราวเฉพาะชุดทดสอบ และผ่าน native Docker ใน WSL ไม่ได้ทดสอบ LAN/Internet/Windows Firewall จริง ดู Microsoft WSL Networking สำหรับ topology ของเครื่ององค์กร'))
manual('install-windows', 'คู่มือติดตั้งบน Windows 11', 'ใช้ Ubuntu 24.04 ผ่าน WSL2 แยกระบบให้ชัดเจน', [PREP, WINDOWS, WSL_SERVICE, TERMINAL, UBUNTU_TOOLS, SOURCE, WSL_NETWORK, TLS, ONBOARD, VERIFY, BACKUP, TROUBLE], 'ติดตั้ง Production ใน Linux WSL2 และเปิดเว็บจาก Windows ได้จริง การตั้ง Windows ใหม่ การเปิด LAN/Internet และการเริ่มระบบหลังรีบูต ยังไม่ได้ยืนยันจากการรันจริง ให้ IT ตรวจรับก่อนเปิดบริการ')

ADMIN_CHAPTERS = [
('เข้าระบบและรู้จักสิทธิ์', steps('เปิดเว็บไซต์ที่ IT แจ้งลงท้าย /login ใช้ admins และรหัสแรก P@ssw0rd112233 เฉพาะการติดตั้งใหม่ เปลี่ยนรหัสอย่างน้อย10ตัวอักษรทันที', 'หลังเปลี่ยนรหัสจะเห็นเมนูด้านซ้าย หากจอเล็กให้กดเมนู เลือกหัวข้อที่ต้องการ', 'บัญชี admins เป็นบัญชีสงวน คนอื่นแก้ชื่อ บทบาท สถานะ หรือรีเซ็ตให้ไม่ได้ เจ้าของเปลี่ยนรหัสของตัวเองได้', 'แอดมินรองสร้างได้หลายคน Instructor ต้องได้รับมอบหมายหมวด ร้านต้องได้รับมอบหมายร้านและอนุมัติ') + fig('dashboard', 'ภาพรวม Admin: เมนูด้านซ้ายใช้เปลี่ยนงาน ตัวเลขสรุปด้านบนและรายการหลักสูตรอยู่ในเนื้อหาหลัก') + note('บัญชีผู้ดูแลเป็นรายบุคคล ไม่ส่งรหัส admins ให้ทุกคน ผู้ลืมรหัสติดต่อ Admin ส่วนรหัสของบัญชีสงวนให้เจ้าของจัดการเอง')),
('ตั้งชื่อ ภาพ และข้อความหน่วยงาน', steps('เลือก บริหารระบบ → ตั้งค่าเว็บไซต์ ตรวจแต่ละกลุ่มตั้งค่า', 'เปลี่ยนชื่อหน่วยงาน ชื่อเว็บไซต์ ข้อความ Header คำต้อนรับ และข้อมูลติดต่อให้ตรงหน่วยงาน', 'อัปโหลดโลโก้/แบนเนอร์หรือเลือกภาพที่ระบบรองรับ ตรวจตัวอย่างก่อนบันทึก', 'กดบันทึก แล้วเปิดหน้า login หรือ dashboard ใหม่เพื่อตรวจข้อความจริง ถ้าไม่พบการเปลี่ยนให้รีเฟรชหน้า') + fig('settings', 'หน้าตั้งค่าองค์กร: ใช้ภาพและข้อความของหน่วยงาน ตรวจตัวอย่างบนหน้าจอก่อนบันทึก') + p('ตั้งค่าภาพ/ข้อความได้โดยไม่แก้โค้ด ค่าโครงสร้างหลัก เช่น APP_KEY รหัสฐานข้อมูล และ ThaiD ให้ผู้ดูแลเซิร์ฟเวอร์จัดการตามคู่มือติดตั้ง')),
('นำเข้าข้อมูลพื้นฐานจาก Excel', flow('ดาวน์โหลดเทมเพลต', 'กรอกข้อมูล', 'ตรวจไฟล์', 'ตรวจตัวอย่าง', 'ยืนยัน') + steps('เลือก นำเข้าข้อมูลพื้นฐาน แล้วเลือกหัวข้อ แผนก/ตำแหน่ง/หมวด/ผู้ใช้/ร้าน', 'กดดาวน์โหลดเทมเพลตแต่ละหัวข้อ เปิดไฟล์ใน Excel ใช้ชีต Data กรอกตั้งแต่แถว2 อย่าเปลี่ยนชื่อชีตหรือหัวตาราง', 'นำเข้าแผนกและตำแหน่งก่อนผู้ใช้ เพราะผู้ใช้จะอ้างรหัสเหล่านี้ ใช้รหัสหมวดและร้านขององค์กรเอง', 'บันทึกเป็น .xlsx ไม่เกิน10MB/1,000แถวต่อไฟล์ ไม่ใส่สูตร/macros/ลิงก์ภายนอก', 'เลือกไฟล์ กด ตรวจไฟล์และแสดงตัวอย่าง ตรวจจำนวนเพิ่มใหม่/ข้ามซ้ำทุกครั้ง แล้วกด ยืนยันนำเข้า ภายใน30นาที') + fig('import-users-preview', 'ตัวอย่างก่อนนำเข้า: ตรวจจำนวนเพิ่มใหม่ ชื่อและรหัสอ้างอิงก่อนกดยืนยัน ไม่มีการเพิ่มข้อมูลในขั้นตรวจไฟล์')),
('กรอกเลขประจำตัวและจัดการข้อมูลซ้ำ', table(['คอลัมน์ผู้ใช้', 'วิธีกรอก'], [['หมายเลขประจำตัว', 'ตัวเลข1–15หลัก เก็บเป็น Text เลือกคอลัมน์ใน Excel → Home → Number Format → Text ก่อนพิมพ์ เลข0นำหน้าต้องอยู่ครบ'], ['รหัสบุคลากร', 'รหัสไม่ซ้ำ เช่น EMP001 หากเว้นว่างระบบใช้ username'], ['ชื่อ / นามสกุล', 'แยกคนละคอลัมน์ ใช้ชื่อจริงตอนเปิดบริการ'], ['รหัสแผนก / รหัสตำแหน่ง', 'ใช้รหัสที่นำเข้าแล้ว ไม่ใส่ชื่อแทนรหัส'], ['อีเมล / โทรศัพท์ / ประเภทบุคลากร', 'กรอกตามหัวตาราง เว้นช่องที่ไม่จำเป็นได้ ไม่ใส่สูตร']]) + fig('import-duplicates', 'เมื่อนำเข้าเลขประจำตัวเดิมซ้ำ ระบบข้ามรายการเหล่านั้นและไม่เปลี่ยนข้อมูลเดิม') + p('เลขประจำตัวซ้ำในไฟล์หรือในฐานข้อมูลจะข้าม ไม่เพิ่มซ้ำ แต่รหัสบุคลากร/อีเมลชนกับคนอื่น หรือรหัสข้อมูลพื้นฐานอื่นซ้ำจะเป็นข้อผิดพลาด ต้องแก้ก่อนนำเข้าทั้งชุด ผู้ใช้ใหม่ทั้งหมดเป็นผู้เรียน รหัสแรก learn123456 และบังคับเปลี่ยน ไม่ได้รับสิทธิ์ Admin/ร้านจาก Excel')),
('เมื่อ Excel ไม่ผ่าน และแก้บัญชีผู้ใช้', steps('อ่านแถวและคอลัมน์ที่ระบบแจ้ง เปิด Excel ไปที่แถวนั้น แก้ข้อมูลแล้วบันทึกใหม่', 'หากเลือกไฟล์ผิดหัวข้อให้เลือกใหม่ ไม่แก้หัวตารางเพื่อหลอกให้ผ่าน', 'บัญชีบุคลากร → ค้นหาคน → แก้ไข เลือกแผนก ตำแหน่ง สถานะและบทบาท แล้วบันทึก', 'Admin รีเซ็ตรหัสผู้ใช้อื่นได้ตามสิทธิ์ ระบบให้เปลี่ยนรหัสใหม่อีกครั้ง อย่าใช้การนำเข้าซ้ำเพื่อรีเซ็ต') + fig('import-error', 'ตัวอย่างข้อผิดพลาด: เทมเพลตไม่ตรงหัวข้อ ต้องใช้ไฟล์ที่ดาวน์โหลดจากหัวข้อเดียวกัน') + fig('users', 'บัญชีบุคลากร: ค้นหาและแก้ไขรายบุคคล บัญชี admins จะถูกสงวน')),
('มอบหมาย Instructor และตรวจขอบเขต', steps('เลือกหมวดหลักสูตรที่ต้องการ แล้วกำหนดผู้ใช้ที่เป็น Instructor ให้ควบคุมหมวดนั้น', 'ตรวจบทบาทในบัญชีบุคลากรและการมอบหมายหมวดให้ครบ Instructorควบคุมหลักสูตรทั้งหมดในหมวดที่ Adminกำหนด', 'ให้ Instructor เข้าระบบด้วยบัญชีของตน ตรวจว่าเห็นเฉพาะหมวดที่มอบหมาย', 'แผนก/ตำแหน่งปัจจุบันของคนแก้ได้ แต่รายงานรอบเก่าใช้ข้อมูล ณ สมัครเรียนเพื่อรักษาประวัติ') + fig('categories', 'หมวดหลักสูตรและการมอบหมาย Instructor โดย Admin') + fig('roles', 'บทบาทและสิทธิ์: ใช้ตรวจขอบเขต ไม่มอบหมาย Admin ให้ผู้เรียนทั่วไป')),
('สร้างหลักสูตรและกำหนดจำนวนบท', steps('เลือก จัดการหลักสูตร → สร้างหลักสูตร กรอกรหัส ชื่อ หมวด และรายละเอียด แล้วบันทึก', 'เข้าแก้หลักสูตร เลือกเวอร์ชันร่าง สร้างกลุ่มบท/บทเรียนตามจำนวนที่ต้องการ กำหนดลำดับและบทจำเป็น', 'ในแต่ละบทเพิ่มเนื้อหาเป็นวิดีโอ เอกสาร ภาพ บทความ หรือลิงก์ จะไม่แนบเอกสารก็ได้', 'วิดีโอเลือกอัปโหลด MP4 หรือ YouTube หรือ URL .mp4โดยตรง ลิงก์ต้องเข้าถึงผ่าน HTTPS และใส่ระยะเวลาเมื่อแบบฟอร์มกำหนด', 'แนบ PDF/ภาพ/ลิงก์กับบทนั้นและตั้งจำเป็นตามต้องการ เอกสารของบทแสดงใต้คลิปอัตโนมัติ ไฟล์อัปโหลดสูงสุด100MB') + fig('course-create', 'สร้างหลักสูตร: ชื่อ หมวด และรายละเอียดเป็นข้อมูลที่ผู้เรียนเห็น') + fig('lesson-upload', 'เพิ่มเนื้อหาในบท: เลือกชนิดและแหล่งวิดีโอ พร้อมแนบเอกสารที่ตรงกับบท')),
('นำเข้า Pretest / Posttest แบบ 4–6 ตัวเลือก', steps('เข้าแท็บ นำเข้าข้อสอบ กด ดาวน์โหลดเทมเพลตข้อสอบ Excel ใช้ชีต Questions และหัวตารางเดิม', 'แต่ละแถวมีรหัสข้อไม่ซ้ำ PRETEST/POSTTEST/BOTH คำถาม ตัวเลือก A–Dจำเป็น E/Fเว้นว่างได้ ถ้ามีFต้องมีE', 'คำตอบถูกเป็น A–F หรือ ก–ฉ ได้หนึ่งตัวเลือกเท่านั้น ใส่คะแนนเต็ม หมวดข้อสอบ และคำอธิบายตามเทมเพลต', 'เลือกไฟล์ → ตรวจตัวอย่าง → ยืนยันนำเข้า ตรวจเฉลยของ Pretest/Posttest แยกกัน', 'หากต้องแทนชุดร่าง ใช้ ล้างข้อสอบเดิมเพื่อนำเข้าใหม่ ยืนยันตามหน้าจอ ใช้ได้เฉพาะเวอร์ชันและชุดสอบร่างที่ไม่เคยมีการสอบ หากเผยแพร่แล้วให้สร้างเวอร์ชันใหม่') + fig('questions-preview', 'ตรวจคำถาม ตัวเลือกและเฉลยก่อนนำเข้า รองรับไฟล์เดิม4ตัวเลือกและขยายถึง6ตัวเลือก') + note('จำนวนครั้ง Posttest ไม่อยู่ใน Excel ตั้งที่รอบเรียนในระบบ ไม่มีข้อสอบอัตนัยในรุ่นนี้')),
('ตั้งชุดสอบ เผยแพร่ และเปิดรอบเรียน', steps('ตั้งค่า PretestและPosttest เป็นเผยแพร่ ตรวจจำนวนข้อ เวลาสอบ และการสุ่มตามที่ต้องการ', 'เผยแพร่เวอร์ชันหลักสูตรเมื่อบท/สื่อ/ชุดสอบครบแล้ว เปิดแท็บ รอบเรียนและผู้เรียน', 'กำหนดชื่อรอบ ปีงบประมาณ วันเริ่ม/จบ การสมัครเองหรือมอบหมาย เกณฑ์ดูวิดีโอและจำนวนครั้ง Posttestรวมทั้งหมด', 'จำนวนครั้งเริ่มต้น1 หมายถึงสอบได้รวม1ครั้ง ไม่ใช่1ครั้งแล้วทำซ้ำอีก1ครั้ง ปรับได้1–100แต่ไม่ลดต่ำกว่าที่ใช้แล้ว', 'เปิดสถานะรอบและมอบหมายผู้เรียนตามต้องการ Pretestบังคับก่อนเรียนแต่ไม่บังคับคะแนน Posttestบังคับอย่างน้อย1ครั้งก่อนจบแต่ไม่บังคับผ่าน') + fig('exam-settings', 'ชุดสอบต้องเผยแพร่ก่อนเปิดรอบ ให้ตรวจเฉลยก่อนมีผู้สอบ เพราะหลังมีประวัติจะถูกจำกัดการแก้ไข') + fig('course-session', 'รอบเรียน: Admin/Instructorตั้งจำนวนครั้ง Posttestรวมทั้งหมดและเกณฑ์การเรียนจากระบบ')),
('ติดตามรายงานและแต้ม', steps('เลือกรายงานผลการเรียน กรองปี/รอบ/แผนก/สถานะตามสิทธิ์ แล้วตรวจข้อมูลก่อนส่งออก', 'เลือกส่งออก XLSX/CSV/PDF ตามแบบฟอร์ม รอ workerสร้างไฟล์จนขึ้นพร้อมดาวน์โหลดแล้วกดดาวน์โหลด', 'คะแนนสรุปใช้ Posttestสูงสุด ประวัติแผนก/ตำแหน่งใช้ ณ สมัครเรียน ไม่ย้ายย้อนหลังตามข้อมูลปัจจุบัน', 'แต้มอัตโนมัติ:จบ20 สอบผ่านเกณฑ์30 สูงสุด≥90%เพิ่ม10 อย่างละหนึ่งครั้งต่อคนต่อรอบ สอบซ้ำไม่ให้โบนัสเดิมซ้ำ', 'กรณีปรับแต้มให้ค้นหาคน ระบุจำนวนและเหตุผล ตรวจยอดก่อนยืนยัน ระบบเก็บ Ledger/Audit ไม่แก้หรือลบรายการเดิม') + fig('reports', 'รายงานตามขอบเขตสิทธิ์และเงื่อนไขที่เลือก') + fig('points-earned', 'ตัวอย่างผู้เรียนได้รับ +20 +30 +10 คนละรายการ รวม60แต้มต่อรอบ')),
('อนุมัติร้านและตั้งรางวัลคูปอง', steps('นำเข้าร้านหรือสร้างร้านใหม่ ร้านใหม่อยู่สถานะรออนุมัติ กำหนดผู้ใช้ที่ปฏิบัติงานร้าน', 'Adminตรวจข้อมูลและอนุมัติร้านก่อนเปิดรับคูปอง การนำเข้า Excelไม่เพิ่มสิทธิ์ร้านให้อัตโนมัติ', 'สร้างรางวัล ผูกร้านที่ใช้ได้ ใส่แต้มที่ใช้ มูลค่าส่วนลดและจำนวนคงเหลือ ตรวจหน่วยบาทในหน้าจอ', 'ตัวอย่าง500แต้ม=5บาท /1000แต้ม=10บาท /1500แต้ม=20บาท คูปองมีอายุ90วันและใช้เฉพาะร้านที่ระบุ', 'หากระงับร้านให้ระบุเหตุผลและตรวจผลกระทบต่อคูปองที่ยังไม่ใช้ในรายงานก่อนแจ้งผู้ใช้') + fig('welfare-admin', 'Adminกำหนดร้าน ผู้ปฏิบัติงาน การอนุมัติ และรางวัลคูปอง')),
('ขั้นตอนร้านรับคูปองและทำใบส่งเบิก', steps('ผู้ปฏิบัติงานร้านเข้าระบบ เลือก รับคูปองและส่งเบิก แล้วเลือกร้านของตน', 'ขอผู้เรียนเปิดบัตรออนไลน์ กดแสดงรหัส นำรหัสมากรอกแล้วกด ตรวจคูปอง', 'ตรวจชื่อผู้ถือ ชื่อร้าน มูลค่า วันหมดอายุ หากตรงกดรับคูปองและยืนยัน แล้วจึงให้ส่วนลด ห้ามรับจากภาพบัตรโดยไม่ตรวจระบบ', 'เลือกระยะเวลารายงาน ทำเครื่องหมายคูปองที่ยังไม่ส่งเบิก กดสร้างใบสรุป ตรวจยอดก่อนยืนยัน', 'ดาวน์โหลด PDFหรือCSVส่งหน่วยงานตามช่องทางที่ตกลง ใบนี้ไม่ใช่การบันทึกจ่ายเงินจริง และรายการถูกกันไม่ให้ส่งเบิกซ้ำ') + fig('merchant-preview', 'ร้านตรวจคูปองก่อนรับ รหัสในภาพถูกปิดบังเพื่อสาธิต ภาพบัตรอย่างเดียวไม่ยืนยันว่าคูปองยังใช้ได้') + fig('merchant-claim', 'ใบสรุปส่งเบิก:ยอดรวมและรายการถูกตรึง ดาวน์โหลดPDF/CSVได้')),
('ดู Audit และส่งต่อปัญหาให้ IT', steps('หากสิทธิ์ผิด ให้ตรวจบัญชี บทบาท หมวดและร้านที่มอบหมายก่อนเพิ่มสิทธิ์ใหม่', 'ใช้ Auditตรวจผู้ทำรายการ/วันเวลา การนำเข้า ปรับแต้ม หรือรับคูปอง ไม่แชร์ logที่มีข้อมูลส่วนบุคคล', 'หากเว็บมี419/502/สื่อไม่เปิด ให้แจ้งITพร้อมเวลาที่เกิดและภาพที่ปิดบังความลับ ไม่เปลี่ยน APP_KEY ไม่ล้างฐานข้อมูล', 'ก่อนอัปเดตให้ITสำรองและกู้คืนในระบบแยก ตรวจรายงานและสื่อให้ครบ เจ้าของข้อมูลตัดสินใจการย้อนข้อมูล') + fig('audit', 'Auditช่วยติดตามผู้ทำรายการและเหตุการณ์ตามสิทธิ์') + note('ThaiDยังปิดจนมีข้อมูลเชื่อมต่อองค์กรและทดสอบบนเซิร์ฟเวอร์จริง บทบาทAdminไม่เท่ากับสิทธิ์ลบฐานข้อมูลหรือแก้กุญแจเข้ารหัส'))]
